def rv_ts: if (. // "") == "" then null else (.[0:19] + "Z") end;
def rv_epoch: rv_ts | if . == null then null else (fromdateiso8601? // null) end;
def rv_when: if (. // "") == "" then "—" else (.[0:10] + " " + .[11:16] + " UTC") end;
def rv_dur($a; $b):
  ($a | rv_epoch) as $s | ($b | rv_epoch) as $e
  | if $s == null or $e == null then "—"
    else ($e - $s) as $d
    | if $d < 1 then "under 1 s"
      elif $d < 60 then (($d | floor | tostring) + " s")
      else ((($d / 60) | floor | tostring) + " m " + ((($d | floor) % 60) | tostring) + " s") end
    end;
def rv_num: tostring as $s
  | if ($s | test("^[0-9]{4,}$")) then ([ range(($s | length); 0; -3) | $s[([. - 3, 0] | max):.] ] | reverse | join(",")) else $s end;
def rv_phase:
  (.status.phase // "") as $s
  | if $s == "Merged" then $s
    else (.spec.decision.phase // (if $s == "" then "Proposed" else $s end)) end;
def rv_decision:
  { phase: rv_phase,
    by: (.spec.decision.decidedBy // .status.decidedBy // ""),
    at: (.spec.decision.decidedAt // .status.decidedAt // ""),
    reason: (.spec.decision.reason // .status.reason // ""),
    claim: (.spec.decision.claim // "") };
def rv_has($x): any(.[]?; . == $x);
def rv_gvk:
  if ((.spec.change.format // "") != "yaml") then null
  else (.spec.change.content // "") as $c
    | { gv: ([ $c | match("(?m)^apiVersion:[ \\t]*[\"']?([^\\s\"'#]+)") ][0].captures[0].string // ""),
        kind: ([ $c | match("(?m)^kind:[ \\t]*[\"']?([^\\s\"'#]+)") ][0].captures[0].string // "") }
    | if .gv == "" or .kind == "" then null else . end
  end;
def rv_kindcheck($served; $kinds):
  (.spec.change.format // "") as $f
  | if $f == "markdown" or $f == "diff" then { state: "na" }
    else rv_gvk as $g
    | if $g == null or $served == null then { state: "unknown" }
      elif ($served | rv_has($g.gv) | not) then ($g + { state: "notServed" })
      elif ($kinds[$g.gv] // null) == null then ($g + { state: "unknown" })
      elif ($kinds[$g.gv] | rv_has($g.kind) | not) then ($g + { state: "notServed" })
      else ($g + { state: "served" }) end
    end;
def rv_target:
  ([ (.status.conditions // [])[] | select(.type == "TargetResolved") ][0] // null) as $c
  | if $c == null then { state: "none" }
    elif $c.status == "True" then { state: "found", message: ($c.message // "") }
    elif $c.reason == "NotFoundOrPrivate" then { state: "unverified", message: ($c.message // "") }
    elif $c.reason == "InvalidRepo" then { state: "invalid", message: ($c.message // "") }
    else { state: "unanswered", message: ($c.message // ""), reason: ($c.reason // "") } end;
def rv_pills($served; $kinds):
  rv_kindcheck($served; $kinds) as $k | rv_target as $t
  | [ (if $k.state == "notServed" then { type: "Kind not served", status: "False", color: "orange" }
       elif $k.state == "na" then { type: "Kind check n/a", status: "Unknown", color: "gray" }
       else empty end),
      (if $t.state == "unverified" then { type: "Target unverified", status: "Unknown", color: "gray" }
       elif $t.state == "invalid" then { type: "Target invalid", status: "False", color: "orange" }
       else empty end) ];
def rv_phase_color:
  if . == "Merged" then "green" elif . == "PrOpen" then "blue" elif . == "Failed" then "red" else "gray" end;
def rv_run_color:
  if . == "PartiallyCompleted" then "orange"
  elif . == "Failed" then "red" elif . == "Running" then "blue" else "gray" end;
def rv_sources:
  [ (.spec.evidence // [])[] | (.source // "unknown") ] | group_by(.)
  | map(.[0] + (if length > 1 then " ×" + (length | tostring) else "" end)) | join(" · ");
def rv_root($up; $n):
  if $n > 32 then . elif ($up[.] // null) != null then ($up[.] | rv_root($up; $n + 1)) else . end;
def rv_not_read:
  [ (.status.evidence // {}) | to_entries[]
    | select(.value.ok == false or .value.empty == true)
    | .key + ": " + ((.value.error // .value.note // (if .value.empty == true then "returned nothing" else "not read" end)) | rtrimstr("; ")) ]
  | join(" · ");
def rv_served_gvs: if (.apisError // null) != null then null else (.apis // null) end;
def rv_kinds_by_gv:
  (.kinds // []) | if type == "array" then . else [.] end
  | map(select(type == "object" and (.gv // "") != "") | { key: .gv, value: (.kinds // []) }) | from_entries;
def rv_claim: "review-" + ((.metadata.name // "") | ltrimstr("p-"));
rv_served_gvs as $served
| rv_kinds_by_gv as $kinds
| ((.proposalsError // null) | if . == null then "" else tostring end) as $perr
| ([ ((.proposals.items) // [])[] | select((.status.phase // "Proposed") != "Refused") ]) as $all
| ([ ((.proposals.items) // [])[] | select((.status.phase // "") == "Refused") ] | length) as $refused
| ([ $all[] | select((.status.phase // "") == "Superseded" and (.status.supersededBy // "") != "")
     | { key: .metadata.name, value: .status.supersededBy } ] | from_entries) as $up
| ([ $all[] | select((.status.phase // "") != "Superseded") | .metadata.name ]) as $live
| ([ $all[] | select((.status.phase // "") == "Superseded") | .metadata.name | rv_root($up; 0) ]
   | map(select(. as $r | $live | rv_has($r))) | group_by(.) | map({ key: .[0], value: length }) | from_entries) as $under
| ([ $all[] | select((.status.phase // "") != "Superseded"
                     or (((.metadata.name | rv_root($up; 0)) as $r | $live | rv_has($r)) | not)) ]) as $visible
| def row:
    rv_phase as $ph | rv_decision as $d
    | { name: .metadata.name,
        title: (.spec.title // .metadata.name),
        subject: (.spec.subject // "—"),
        kind: (.spec.kind // "—"),
        sources: (rv_sources | if . == "" then "—" else . end),
        checks: (rv_pills($served; $kinds) | tojson),
        phase: $ph,
        phaseColor: ($ph | rv_phase_color),
        superseded: (($under[.metadata.name] // 0) | if . == 0 then "—" else (tostring + " earlier") end),
        created: (.metadata.creationTimestamp // ""),
        target: (.spec.target.repo // "—"),
        decidedBy: (if $d.by == "" then "—" else $d.by end),
        decidedAt: $d.at,
        outcome: (if (.status.pullRequest.url // "") != "" then .status.pullRequest.url
                  elif $d.reason != "" then $d.reason else (.status.error // "—") end) };
  def grouped:
    group_by(.spec.subject // ("~" + .metadata.name))
    | map(sort_by(.metadata.creationTimestamp // "") | reverse)
    | sort_by(.[0].metadata.creationTimestamp // "") | reverse | add // [];
  ([ $visible[] | select(rv_phase as $p | $p == "Proposed" or $p == "PrOpen") ] | grouped | map(row)) as $open
| ([ $visible[] | select(rv_phase as $p | $p == "Merged" or $p == "Rejected" or $p == "Failed") ] | grouped | map(row)) as $decided
| ([ ((.runs.items) // [])[] ] | sort_by(.status.startedAt // .metadata.creationTimestamp // "") | reverse) as $runs
| ($runs[0] // null) as $last
| ((.cronjob // {}) | if type == "object" and (.kind // "") == "CronJob" and ((.metadata.name // "") != "") and (.spec.jobTemplate.spec != null) then . else null end) as $cron
| { installed: ($perr | test("404|not found|could not find"; "i") | not),
    denied: ($perr | test("403|forbidden"; "i")),
    readError: $perr,
    open: ($open | length),
    rows: $open,
    decided: $decided,
    decidedCount: ($decided | length),
    refused: $refused,
    supersededHidden: ([ $under[] ] | add // 0),
    openCaption: (
      ([ (($open | length) | tostring) + " open"
       , (if ([ $under[] ] | add // 0) > 0 then (([ $under[] ] | add | tostring) + " superseded, counted on the proposal that replaced them") else empty end)
       , "newest first"
       , (if $refused > 0 then ($refused | tostring) + " historical Refused records not listed" else empty end) ]
       | join(" · "))
      + (if $last == null then "" else
          " · last review " + $last.metadata.name + " on " + ($last.status.startedAt | rv_when)
          + " (" + ($last.status.phase // "Pending") + ")" end)),
    decidedCaption: ([ ([ $decided[] | select(.phase == "Merged") ] | length | tostring) + " merged"
                     , ([ $decided[] | select(.phase == "Rejected") ] | length | tostring) + " rejected"
                     , ([ $decided[] | select(.phase == "Failed") ] | length | tostring) + " failed" ] | join(" · ")),
    runRows: [ $runs[] | (.status.phase // "Pending") as $ph
               | { name: .metadata.name,
                   phase: $ph,
                   phaseColor: ($ph | rv_run_color),
                   started: (.status.startedAt // "" | rv_ts // ""),
                   took: rv_dur(.status.startedAt; .status.finishedAt),
                   result: (if $ph == "Failed" then (.status.error // "failed, no error recorded")
                            elif $ph == "Running" or $ph == "Pending" then "in progress"
                            else (((.status.proposals.created // 0) | tostring) + " proposed"
                                  + (if (.status.proposals.superseded // 0) > 0 then " · " + (.status.proposals.superseded | tostring) + " superseded" else "" end)
                                  + (if (.status.proposals.deduplicated // 0) > 0 then " · " + (.status.proposals.deduplicated | tostring) + " duplicate" else "" end)) end),
                   notRead: (rv_not_read | if . == "" then "—" else . end) } ],
    runCaption: (([ $runs | group_by(.status.phase // "Pending")[] | ((length | tostring) + " " + (.[0].status.phase // "Pending")) ] | join(" · "))
                 + (if ($runs | length) > 0 then " · since " + ($runs[-1].status.startedAt | rv_when) else "" end)),
    runCount: ($runs | length),
    lastRun: (if $last == null then null else { name: $last.metadata.name, phase: ($last.status.phase // "Pending"), started: ($last.status.startedAt | rv_when) } end),

    reviewCronJob: (if $cron == null then null else
      { name: $cron.metadata.name, namespace: ($cron.metadata.namespace // "default"), uid: ($cron.metadata.uid // ""),
        jobTemplate: { metadata: ($cron.spec.jobTemplate.metadata // {}), spec: $cron.spec.jobTemplate.spec } } end),

    banner: (
      if ($perr | test("404|not found|could not find"; "i")) then
        { type: "info", title: "The nightly review is not installed on this cluster",
          description: "This page lists review.krateo.io proposals and review runs, and this cluster serves no such API. Once the nightly review component is installed, its first run's proposals appear here." }
      elif ($perr | test("403|forbidden"; "i")) then
        { type: "warning", title: "Your role cannot read review proposals",
          description: "Listing review.krateo.io proposals in this namespace was refused for your account. An administrator can grant read access to proposals and reviewruns." }
      elif $last == null then
        { type: "info", title: "No review has run yet",
          description: "The nightly review reads the last 24 hours of this platform's telemetry and agent sessions. Its proposals appear here, and nothing is applied." }
      elif (($last.status.phase // "Pending") == "Running" or ($last.status.phase // "Pending") == "Pending") then
        { type: "info", title: ("A review is running: " + $last.metadata.name),
          description: ("Started " + ($last.status.startedAt | rv_when)
                        + ([ ($last.status.steps // [])[] | select(.phase == "Running") | " · current step: " + .name ][0] // "")
                        + ". The proposals below come from runs that finished.") }
      elif ($last.status.phase // "") == "Failed" then
        { type: "error", title: ("The last review failed: " + $last.metadata.name),
          description: ("It stopped after " + rv_dur($last.status.startedAt; $last.status.finishedAt) + ": "
