${ [ { resourceRefId: "review-proposal-header" } ] + (if (.found // false) | not then [ { resourceRefId: "review-proposal-missing" } ]
   else ((if (.kindAlert // "") != "" then [ { resourceRefId: "review-proposal-kind" } ] else [] end)
       + (if (.targetAlert // "") != "" then [ { resourceRefId: "review-proposal-target" } ] else [] end)
       + (if (.lineageAlert // "") != "" then [ { resourceRefId: "review-proposal-lineage" } ] else [] end)
       + [ { resourceRefId: "review-proposal-body" } ]) end) }

${ { type: "object",
     required: ["replicas"],
     properties: {
       replicas: { type: "integer", title: "Replicas", minimum: 0, maximum: 20,
                   description: "0 stops the component. The rollout is immediate." } } } }

${ [ (.items // [])[]
    | { rootName, slug, created,
        widgetsLabel: ("\(.widgets // 0) widget" + (if (.widgets // 0) == 1 then "" else "s" end)) } ] }

${ if (.found // false) | not then []
   else [ { label: .kind, color: "gray" }, { label: .phase, color: .phaseColor } ]
        + (if (.subject // "") != "" then [ { label: .subject, color: "gray" } ] else [] end) end }

${ "Checked as user " + (.username // "?")
  + (if ((.groups // []) | length) > 0
     then " + groups [" + (.groups | join(", ")) + ", system:authenticated]"
     else " — groups unknown (IdP-managed identity): user-only check, group-granted access may be understated" end)
  + " · run as the calling admin via SubjectAccessReview, in namespace " + (.ns // "") }

${ if (.available // false) then
    [ (.rows // [])[] | [
      {valueKey:"capability",kind:"jsonSchemaType",type:"string",stringValue:(.capability // "")},
      {valueKey:"scope",kind:"jsonSchemaType",type:"string",stringValue:(.scope // "")},
      {valueKey:"allowed",kind:"tag",stringValue:(if (.allowed // false) then "Allowed" else "No access" end),color:(if (.allowed // false) then "green" else "red" end)}
    ] ]
  else
    [ [
      {valueKey:"capability",kind:"jsonSchemaType",type:"string",stringValue:"Preview unavailable — creating SubjectAccessReviews needs cluster-wide permission your account lacks"},
      {valueKey:"scope",kind:"jsonSchemaType",type:"string",stringValue:"—"},
      {valueKey:"allowed",kind:"tag",stringValue:"Unavailable",color:"default"}
    ] ]
  end }

${ [ (.delegateRows // [])[] | [ { valueKey: "agent", kind: "jsonSchemaType", type: "string", stringValue: (.name // "") },
    { valueKey: "role",  kind: "jsonSchemaType", type: "string", stringValue: (.role // ""), color: "var(--gray-color)" },
    (if (.routeIsException // false)
     then { valueKey: "route", kind: "tag", stringValue: (.route // ""), color: "orange" }
     else { valueKey: "route", kind: "jsonSchemaType", type: "string", stringValue: (.route // "") } end),
    (if ((.status // "") == "")
     then { valueKey: "status", kind: "jsonSchemaType", type: "string", stringValue: "" }
     else { valueKey: "status", kind: "tag", stringValue: (.status), color: (if ((.statusColor // "") == "") then "orange" else .statusColor end) } end),
    { valueKey: "routeNs",   kind: "jsonSchemaType", type: "string", stringValue: (.routeNs // "") },
    { valueKey: "routeName", kind: "jsonSchemaType", type: "string", stringValue: (.routeName // "") } ] ] }

${ [ (.envRows // [])[] | [ { valueKey: "name",     kind: "jsonSchemaType", type: "string", stringValue: (.name // "") },
    { valueKey: "declared", kind: "jsonSchemaType", type: "string", stringValue: (.declared // ""), color: "var(--gray-color)" },
    (if (.drift // false)
     then { valueKey: "running", kind: "tag", stringValue: (.running // ""), color: "orange" }
     else { valueKey: "running", kind: "jsonSchemaType", type: "string", stringValue: (.running // ""), color: "var(--gray-color)" } end) ] ] }

${ [ (.serverRows // [])[] | [ { valueKey: "server",   kind: "jsonSchemaType", type: "string", stringValue: (.server // "") },
    (if (.boundIsException // false)
     then { valueKey: "bound", kind: "tag", stringValue: (.bound // ""), color: "orange" }
     else { valueKey: "bound", kind: "jsonSchemaType", type: "string", stringValue: (.bound // "") } end),
    { valueKey: "tools",    kind: "jsonSchemaType", type: "string", stringValue: (.tools // ""), color: "var(--gray-color)" },
    (if ((.gated // "") == "")
     then { valueKey: "gated", kind: "jsonSchemaType", type: "string", stringValue: "" }
     else { valueKey: "gated", kind: "tag", stringValue: (.gated), color: "orange" } end),
    { valueKey: "endpoint", kind: "jsonSchemaType", type: "string", stringValue: (.endpoint // ""), color: "var(--gray-color)" },
    (if (.routeIsException // false)
     then { valueKey: "route", kind: "tag", stringValue: (.route // ""), color: "orange" }
     else { valueKey: "route", kind: "jsonSchemaType", type: "string", stringValue: (.route // "") } end) ] ] }

${ [
  { label: ((.analyzedRows // [] | length | tostring) + " resources"), resourceRefId: "incident-analyzed" },
  { label: ((.sourcesRows  // [] | length | tostring) + " sources"),   resourceRefId: "incident-sources-table" }
] }
